// Excerpt of the file as the worktree carries it. Elisions are marked.

export function outOfScopeChangedPaths(args: {
  changedFiles: readonly string[];
  manifest: AcceptanceManifest;
  sliceArtifactDir: string;
  acceptedPairIntact: boolean;
  options?: LaneResourceOptions;
}): string[] {
  const { changedFiles, manifest, sliceArtifactDir, acceptedPairIntact, options } = args;
  const declared = new Set(acceptanceManifestPaths(manifest));
  /* … the orchestrator-owned carve-out elided … */
  const offenders: string[] = [];

  for (const raw of changedFiles) {
    const display = displayPath(raw);
    let key: string;
    try {
      key = normalizeAcceptanceManifestPath(raw);
    } catch {
      offenders.push(display);
      continue;
    }
    /* … prefix exemptions elided … */
    if (!declared.has(key)) offenders.push(display);
  }
  return offenders;
}
